 1	package org.tomasa.mandarina.utils;
 2	
 3	import java.io.ByteArrayInputStream;
 4	import java.io.ByteArrayOutputStream;
 5	import java.io.IOException;
 6	import java.util.ArrayList;
 7	
 8	import org.bukkit.NamespacedKey;
 9	import org.bukkit.entity.Player;
 10	import org.bukkit.inventory.ItemStack;
 11	import org.bukkit.persistence.PersistentDataContainer;
 12	import org.bukkit.persistence.PersistentDataType;
 13	import org.bukkit.util.io.BukkitObjectInputStream;
 14	import org.bukkit.util.io.BukkitObjectOutputStream;
 15	import org.tomasa.mandarina.Mandarina;
 16	
 17	import java.util.Base64;
 18	
 19	public class VaultUtils {
 20	 public static void saveItems(Player player, ItemStack[] items) {
 21	 try {
 22	 ByteArrayOutputStream io = new ByteArrayOutputStream();
 23	 BukkitObjectOutputStream out = new BukkitObjectOutputStream(io);
 24	
 25	 out.writeInt(items.length);
 26	
 27	 for (ItemStack item : items) {
 28	 out.writeObject(item);
 29	 }
 30	
 31	 out.close();
 32	
 33	 String encoded = Base64.getEncoder().encodeToString(io.toByteArray());
 34	
 35	 player.getPersistentDataContainer().set(
 36	 new NamespacedKey(Mandarina.getPlugin(), "vault"),
 37	 PersistentDataType.STRING,
 38	 encoded
 39	 );
 40	 } catch (IOException ex) {
 41	 ex.printStackTrace();
 42	 }
 43	 }
 44	
 45	 public static ArrayList<ItemStack> getItems(Player player) {
 46	 PersistentDataContainer data = player.getPersistentDataContainer();
 47	 ArrayList<ItemStack> items = new ArrayList<>();
 48	
 49	 String encodedItems = data.get(
 50	 new NamespacedKey(Mandarina.getPlugin(), "vault"),
 51	 PersistentDataType.STRING
 52	 );
 53	
 54	 if (encodedItems == null || encodedItems.isEmpty()) {
 55	 return new ArrayList<>();
 56	 }
 57	
 58	 byte[] rawData = Base64.getDecoder().decode(encodedItems);
 59	
 60	 try {
 61	 ByteArrayInputStream io = new ByteArrayInputStream(rawData);
 62	 BukkitObjectInputStream in = new BukkitObjectInputStream(io);
 63	
 64	 int itemsCount = in.readInt();
 65	
 66	 for (int i = 0; i < itemsCount; i++) {
 67	 items.add((ItemStack) in.readObject());
 68	 }
 69	
 70	 in.close();
 71	
 72	 } catch (IOException | ClassNotFoundException ex) {
 73	 ex.printStackTrace();
 74	 }
 75	
 76	 return items;
 77	 }
 78	 
 79	}
