 19	
 20	 @Override
 21	 public void onEnable() {
 22	 instance = this;
 23	
 24	 // Plugin startup logic
 25	 Bukkit.getConsoleSender().sendMessage(ChatColor.translateAlternateColorCodes(
 26	 '&', prefix + " &aPlugin iniciado en la versión: &b" + version));
 27	
