 30	
 31	 private void registerCommands() {
 32	 Objects.requireNonNull(this.getCommand("mandarina")).setExecutor(new InfoCommand(this));
 33	 Objects.requireNonNull(this.getCommand("muerte")).setExecutor(new deathCommand());
