 12	 @Override
 13	 public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command, @NotNull String label, @NotNull String[] args) {
 14	 // Check if sender is a player
 15	 if (!(sender instanceof Player)) {
 16	 sender.sendMessage(messageutil.getColoredMessage("&cEste comando solo puede ser usado por jugadores."));
 17	 return true;
 18	 }
 19	
 20	 // Check if command has correct number of arguments
 21	 if (args.length != 1) {
 22	 sender.sendMessage(messageutil.getColoredMessage("&cEl comando tiene la siguiente sintaxis: /s <jugador>"));
 23	 return true;
 24	 }
 25	
 26	 Player player = (Player) sender;
 27	 Player target = Bukkit.getPlayer(args[0]);
 28	
 29	 // Check if target player exists
 30	 if (target == null) {
 31	 sender.sendMessage(messageutil.getColoredMessage("&cEl jugador no existe o está desconectado."));
 32	 return true;
 33	 }
 34	
 35	 // Check if target is the same as sender
 36	 if (target == player) {
 37	 sender.sendMessage(messageutil.getColoredMessage("&cNo puedes traerte a ti mismo."));
 38	 return true;
 39	 }
 40	
 41	 // Check if target is online
 42	 if (!target.isOnline()) {
 43	 sender.sendMessage(messageutil.getColoredMessage("&cEl jugador no está en línea."));
 44	 return true;
 45	 }
 46	
 47	 // Teleport target to player
 48	 target.teleport(player.getLocation());
 49	
 50	 // Send success messages
 51	 sender.sendMessage(messageutil.getColoredMessage("&fEl jugador &b&l" + target.getName() + "&r&f ha sido teletransportado a ti."));
 52	 target.sendMessage(messageutil.getColoredMessage("&fHas sido teletransportado a &b&l" + player.getName() + "&r&f."));
 53	
 54	 return true;
 55	 }
