 9	
 10	 @Override
 11	 public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
 12	 if (sender instanceof Player player) {
 13	 if (args.length == 0) {
 14	 player.sendMessage("Usage: /tp <player>");
 15	 return true;
 16	 }
 17	 Player target = Bukkit.getPlayer(args[0]);
 18	 if (target != null && target.isOnline()) {
 19	 player.teleport(target);
 20	 player.sendMessage("Teleported to " + target.getName());
 21	 } else if(!(target.isOnline())){
 22	 player.sendMessage("Player is offline.");
 23	 } else {
 24	 player.sendMessage("Player does'nt found.");
 25	 }
 26	 } else {
 27	 sender.sendMessage("This command can only be used by players.");
 28	 }
 29	 return true;
 30	 }
