 29	 return true;
 30	 }else if (target == player) {
 31	 sender.sendMessage(messageutil.getColoredMessage("&cNo puedes traerte a ti mismo."));
 32	 return true;
 33	 }else if (!target.isOnline()) {
 34	 sender.sendMessage(messageutil.getColoredMessage("&cEl jugador no está en línea."));
 35	 return true;
 36	 }
 37	 if (args.length == 1) {
 38	 sender.sendMessage(messageutil.getColoredMessage("&fEl jugador &b&l" + target.getName() + "&r&f ha sido teletransportado a ti."));
 39	 target.teleport(player.getLocation());
 40	 player.sendMessage(messageutil.getColoredMessage("&fhas sido teletransportado a&b&l " + target.getName() + "&f&r."));
